<script lang="ts">
  import { gameSession } from '$lib/stores/gameStore';
  import type { GameState } from '$lib/domain/types';
  let { game } = $props<{ game: GameState }>();
  function resolve(): void { gameSession.updateGame((state) => { const victory = state.haven.defense + state.ships.length * 18 >= state.defense.attackStrength; return { ...state, screen: 'haven', defense: { ...state.defense, active: false, stage: 'resolved', outcome: victory ? 'victory' : 'defeat', damage: victory ? ['해안 목책 경미한 손상'] : ['창고 약탈', '부두 파손'] }, haven: { ...state.haven, raidThreat: 0, defense: victory ? state.haven.defense : Math.max(0, state.haven.defense - 12) }, resources: victory ? state.resources : { ...state.resources, gold: Math.max(0, state.resources.gold - 180), food: Math.max(0, state.resources.food - 24), timber: Math.max(0, state.resources.timber - 16) } }; }, true); }
</script>
<section class="event-screen"><article class="event-card panel" style="text-align:center"><span class="eyebrow danger">HAVEN UNDER ATTACK</span><h1 style="font-size:4rem">검은 깃발을 지켜라</h1><p class="muted">적 함대가 만 입구에 모습을 드러냈습니다. 포대와 주둔 함선을 배치하고 상륙대를 저지하십시오.</p><div class="versus"><div class="force-card"><span class="eyebrow">본거지 방어</span><div class="force-number">{game.haven.defense + game.ships.length * 18}</div></div><div class="versus-mark">⚔</div><div class="force-card"><span class="eyebrow danger">침공 전력</span><div class="force-number">{game.defense.attackStrength}</div></div></div><div class="action-grid" style="margin-top:1rem"><button class="btn" onclick={() => gameSession.updateGame((state) => ({ ...state, defense: { ...state.defense, defenseStrength: state.defense.defenseStrength + 18 } }))}>해안 포대 집중</button><button class="btn" onclick={() => gameSession.updateGame((state) => ({ ...state, defense: { ...state.defense, defenseStrength: state.defense.defenseStrength + state.ships.length * 12 } }))}>함대 출격</button><button class="btn primary" onclick={resolve}>방어전 개시</button></div></article></section>
